{
  "name": "update_search_filters",
  "description": "Edit the job search filters to match the user's latest message.",
  "strict": true,
  "input_schema": {
    "type": "object",
    "properties": {
      "reset": {"type": "boolean"},
      "set": {
        "type": "object",
        "properties": {
          "role":       {"type": ["string", "null"]},
          "level":      {"type": ["string", "null"]},
          "location":   {"type": ["string", "null"]},
          "remote":     {"type": ["boolean", "null"]},
          "salary_min": {"type": ["integer", "null"]}
        },
        "required": ["role", "level", "location", "remote", "salary_min"],
        "additionalProperties": false
      },
      "remove": {"type": "array", "items": {"type": "string", "enum": ["role", "level", "location", "remote", "salary_min"]}}
    },
    "required": ["reset", "set", "remove"],
    "additionalProperties": false
  }
}

SLOTS = ["role", "level", "location", "remote", "salary_min"]

def apply_diff(state, diff):
    new = dict(state)                    # carryover by default
    if diff["reset"]:
        new = {k: None for k in SLOTS}
    for k, v in diff["set"].items():
        if v is not None:
            new[k] = v                   # add or replace
    for k in diff["remove"]:
        new[k] = None                    # remove
    return new

def to_query(s):
    parts = []
    if s["role"]: parts.append('"%s"' % s["role"])
    if s["level"]: parts.append("level:" + s["level"])
    if s["location"]: parts.append("location:" + s["location"])
    if s["remote"] is not None: parts.append("remote:true" if s["remote"] else "remote:false")
    if s["salary_min"] is not None: parts.append("salary_min>=%d" % s["salary_min"])
    return " AND ".join(parts)
